WITH scored AS (SELECT id, dept_id, manager_id, job_title, salary, hire_date, is_remote, level, ROW_NUMBER() OVER w_recent AS seq_no, LAST_VALUE(job_title, TRUE) OVER (PARTITION BY dept_id ORDER BY salary, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_job_title, SUM(salary) OVER w_recent_2 AS running_salary FROM employees WINDOW w_recent AS (PARTITION BY job_title, manager_id ORDER BY salary DESC, id), w_recent_2 AS (PARTITION BY job_title, level ORDER BY salary, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)) SELECT s.id, s.manager_id, s.job_title, s.salary, s.hire_date, s.is_remote, s.level, s.seq_no, s.last_known_job_title, CASE WHEN level RLIKE '^(L3|L4)$' THEN 'OTHER_ZONE' WHEN level RLIKE '^(L1|L2)$' THEN 'CORE' ELSE 'EXTENDED' END AS level_zone, (SELECT MAX(e2.salary) FROM employees e2 WHERE e2.manager_id = s.manager_id) AS max_employee_salary FROM scored s ORDER BY level NULLS LAST;
